const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]).buffer(20000); // 20km buffer around Wuhan
  const band = 'NO2_column_number_density';
  const collection = 'COPERNICUS/S5P/OFFL/L3_NO2';

  const date_before_start = '2020-01-01';
  const date_before_end = '2020-01-20';
  const date_after_start = '2020-02-10';
  const date_after_end = '2020-02-25';

  // Function to filter by quality assurance value (QA > 0.75 is recommended)
  function maskByQA(image) {
    return image.updateMask(image.select('qa_value').gt(0.75));
  }

  // 2. Data Acquisition & Check
  const col_before = ee.ImageCollection(collection)
    .filterBounds(wuhan)
    .filterDate(date_before_start, date_before_end)
    .select([band, 'qa_value'])
    .map(maskByQA);

  const col_after = ee.ImageCollection(collection)
    .filterBounds(wuhan)
    .filterDate(date_after_start, date_after_end)
    .select([band, 'qa_value'])
    .map(maskByQA);

  const count_before_images = col_before.size().getInfo();
  const count_after_images = col_after.size().getInfo();

  if (count_before_images === 0 || count_after_images === 0) {
    console.log(`Image count Jan 1-20: ${count_before_images}`);
    console.log(`Image count Feb 10-25: ${count_after_images}`);
    console.log('C1: Empty Collection');
    return;
  }

  // 3. Processing
  const mean_img_before = col_before.select(band).mean();
  const mean_img_after = col_after.select(band).mean();

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats_before = mean_img_before.reduceRegion({
    reducer: reducer,
    geometry: wuhan,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats_after = mean_img_after.reduceRegion({
    reducer: reducer,
    geometry: wuhan,
    scale: 3000,
    maxPixels: 1e9
  });

  const mean_before = stats_before.get(band + '_mean').getInfo();
  const pixels_before = stats_before.get(band + '_count').getInfo();

  const mean_after = stats_after.get(band + '_mean').getInfo();
  const pixels_after = stats_after.get(band + '_count').getInfo();

  // 4. Validation & Final Answer
  if (pixels_before === 0 || pixels_after === 0) {
    console.log(`Valid pixels Jan 1-20: ${pixels_before}`);
    console.log(`Valid pixels Feb 10-25: ${pixels_after}`);
    console.log('C2: No Valid Pixels');
    return;
  }

  if (mean_before === null || mean_after === null) {
      console.log(`Mean NO2 Jan (mol/m^2): ${mean_before}`);
      console.log(`Mean NO2 Feb (mol/m^2): ${mean_after}`);
      console.log('C3: Calculation Failure');
      return;
  }

  console.log(`Mean NO2 Jan 1-20 (mol/m^2): ${mean_before.toExponential(3)}`);
  console.log(`Mean NO2 Feb 10-25 (mol/m^2): ${mean_after.toExponential(3)}`);

  if (mean_after < mean_before) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
